css:
body :where([data-bz-node="sr"]) .bz-block{padding:0}
body :where([data-bz-node="sr"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="sr"]>.bz-container{padding-inline:0}

body [data-bz-node="sr"]{background:var(--paper);padding:0}
body [data-bz-node="sr"]>.bz-container{max-width:none}
body [data-bz-node="sr-row"]{display:grid;grid-template-columns:1fr 1fr;gap:0;min-height:520px}
body [data-bz-node="sr-row"]>.bz-col{grid-column:auto}
body [data-bz-node="sr-copy"]{display:flex;flex-direction:column;justify-content:center;padding:80px max(24px,calc((100vw - 1188px)/2)) 80px 72px;box-sizing:border-box}
body [data-bz-node="sr-h"] .bz-eyebrow{font:700 10.5px/1.4 var(--font-body);letter-spacing:.22em;text-transform:uppercase;color:#6b6b6a;margin:0 0 14px}
body [data-bz-node="sr-h"] h2{font:700 36px/1.08 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0;max-width:520px}
body [data-bz-node="sr-text"] .bz-text{max-width:520px;margin-top:24px}
body [data-bz-node="sr-text"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0;margin:0 0 14px}
body [data-bz-node="sr-text"] p:last-child{margin:0}
body [data-bz-node="sr-text"] a{color:var(--accent);text-decoration:none}
body [data-bz-node="sr-text"] a:hover{text-decoration:underline}
body [data-bz-node="sr-pts"]{display:block;margin-top:24px}
body [data-bz-node^="sr-pt-"]{display:block;margin-bottom:9px}
body [data-bz-node^="sr-ptx-"] p{position:relative;padding-left:20px;font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0}
body [data-bz-node^="sr-ptx-"] p::before{content:"";position:absolute;left:2px;top:9px;width:6px;height:6px;background:var(--accent)}
body [data-bz-node="sr-link"]{margin-top:26px}
body [data-bz-node="sr-link"] .bz-btns{margin:0}
body [data-bz-node="sr-link"] .bz-btn{padding:0;border:0;background:none;color:var(--ink);font:700 10.5px/1 var(--font-body);letter-spacing:.16em;text-transform:uppercase;text-decoration:none;gap:10px;height:auto;min-height:0}
body [data-bz-node="sr-link"] .bz-btn::after{content:"";width:13px;height:13px;background:currentColor;-webkit-mask:url(/icons/arrow-right.svg) center/13px no-repeat;mask:url(/icons/arrow-right.svg) center/13px no-repeat}
body [data-bz-node="sr-link"] .bz-btn:hover{color:var(--accent)}
body [data-bz-node="sr-media"]{position:relative;min-height:420px}
body [data-bz-node="sr-media"] .bz-block,body [data-bz-node="sr-media"] .bz-container,body [data-bz-node="sr-media"] figure{height:100%;margin:0}
body [data-bz-node="sr-media"] img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;border-radius:0}
@media (max-width:1100px){
  body [data-bz-node="sr-row"]{grid-template-columns:1fr}
  body [data-bz-node="sr-copy"]{padding:56px 24px}
  body [data-bz-node="sr-media"]{min-height:0;aspect-ratio:16/10;order:-1}
}
@media (max-width:640px){body [data-bz-node="sr-copy"]{padding:44px 20px}body [data-bz-node="sr-h"] h2{font-size:26px}}

body [data-bz-node="sr-after"] .bz-text{max-width:520px;margin-top:22px}
body [data-bz-node="sr-after"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0;margin:0 0 14px}
body [data-bz-node="sr-after"] p:last-child{margin:0}
